class Solution {
    int m, n;
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};
    vector<vector<int>>* g;

    int dfs(int r, int c) {
        int val = (*g)[r][c];
        (*g)[r][c] = 0;
        int bestPath = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && (*g)[nr][nc] > 0) {
                bestPath = max(bestPath, dfs(nr, nc));
            }
        }
        (*g)[r][c] = val;
        return val + bestPath;
    }

public:
    int getMaximumGold(vector<vector<int>>& grid) {
        m = grid.size();
        n = grid[0].size();
        g = &grid;
        int best = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) {
                    best = max(best, dfs(i, j));
                }
            }
        }
        return best;
    }
};
